```suggestion
  // When memory debugging is enabled, the on-demand heap-snapshot handler is
  // installed inside the child (via `enableMemoryDebuggingMode`). Forward
  // SIGUSR2 to the child so signalling the top-level `next build` process still
  // triggers a snapshot instead of terminating the supervisor (SIGUSR2's
  // default action) and orphaning the build child.
  const memoryDebuggingEnabled =
    process.env.EXPERIMENTAL_DEBUG_MEMORY_USAGE === '1' ||
    process.argv.includes('--experimental-debug-memory-usage')
  const onHeapSnapshot = () => child.kill('SIGUSR2')
  if (memoryDebuggingEnabled) {
    process.on('SIGUSR2', onHeapSnapshot)
  }

  function stopForwardingSignals() {
    process.off('SIGINT', onInterrupt)
    process.off('SIGTERM', onTerminate)
    process.off('SIGHUP', onHangup)
    if (memoryDebuggingEnabled) {
      process.off('SIGUSR2', onHeapSnapshot)
    }
```

Build supervisor doesn\'t forward SIGUSR2 to the child\, so `next build --experimental-debug-memory-usage` heap\-snapshot\-on\-demand kills the top\-level process and orphans the build child\.

